public class GarbageCollectionTuningExample {
    // To run an application with ZGC or Shenandoah, configure JVM flags explicitly.
    // Example flags for production low-latency execution on OpenJDK:
    //
    // ZGC Configuration:
    // java -XX:+UseZGC -Xmx16g -XX:+UnlockDiagnosticVMOptions -jar my-application.jar
    //
    // Shenandoah Configuration:
    // java -XX:+UseShenandoahGC -Xmx16g -XX:ShenandoahGCHeuristics=adaptive -jar my-application.jar

    public static void main(String[] args) {
        System.out.println("Low-latency collectors enabled. Monitoring allocation rates...");
    }
}
